INSERT INTO "public"."complaints" SELECT * FROM json_populate_record(NULL::"public"."complaints", '{"id":1,"complaint_no":"CMP-IMPORTED-0001","customer_name":"GK CONTRACTING W.L.L","delivery_date":"2026-08-10","complaint_type":"Product","material_type":"8\" PLAIN & 8\" SANDWICH","details":"VERY WEAK & NOT INCOHERENT","solution":"The customer complained that a few blocks were received with cracks. The issue was related to the initial stage of production when the machine was starting up. After production started the machine settings were adjusted and the issue was corrected. The labour should have inspected the blocks coming out of the machine and removed any blocks with visible cracks before they were sent for delivery. The customer has already used the blocks.","recommendation":"","picture_paths":[],"created_by":null,"created_at":"2026-09-20T06:45:32.873817+00:00","updated_at":"2026-09-20T07:03:14.966+00:00","status":"complete","qc_reviewer_name":null,"review_date":null}'::json);
INSERT INTO "public"."complaints" SELECT * FROM json_populate_record(NULL::"public"."complaints", '{"id":2,"complaint_no":"CMP-IMPORTED-0002","customer_name":"AL RAWACHED CONSTRUCTION","delivery_date":"2026-07-22","complaint_type":"Product","material_type":"SEBAGO 60MM BUFF EDGE","details":"BAD QUALITY","solution":"Damaged Quantity: Approximately 5–6 pieces During the inspection, a few pavers were found to be brittle and prone to crumbling. The reason is believed to be that these pavers were relatively dry, which may have occurred during the production start-up stage due to water adjustment at the beginning of production. In addition, loading and unloading activities may have contributed to some of the observed damage. A sample of the same paver product was subsequently tested at the Hidd Yard, and the compressive strength was found to comply with the applicable standards. Based on the test results, the customer was reassured and agreed to proceed with using the material. Conclusion: At this stage, no replacement is required, as the damaged quantity is very limited and the material has already been used by the customer without any reported issues.","recommendation":"there are no steps.","picture_paths":[],"created_by":null,"created_at":"2026-09-20T06:45:32.873817+00:00","updated_at":"2026-09-20T07:03:14.974+00:00","status":"complete","qc_reviewer_name":null,"review_date":null}'::json);
INSERT INTO "public"."complaints" SELECT * FROM json_populate_record(NULL::"public"."complaints", '{"id":3,"complaint_no":"CMP-IMPORTED-0003","customer_name":"INSHA W.L.L","delivery_date":"2026-08-23","complaint_type":"Product","material_type":"LARGE RECTANGULAR - BUFF","details":"Different colors in interlock","solution":"The site was visited and approximately 2 sqm of paving blocks were found to have a slightly whitish/lighter color compared to the rest of the supplied material.","recommendation":"","picture_paths":[{"size": 1926518, "mimeType": "image/png", "objectPath": "/objects/uploads/a7619585-e3e1-4bcd-b5da-e9ca211f357f", "originalName": "14dcd6a9-afc5-4c9b-9f6c-9d0221463ca1.png"}, {"size": 45816, "mimeType": "image/jpeg", "objectPath": "/objects/uploads/a81da2a2-4f0d-4417-a66f-4f09374cefac", "originalName": "signeture.jpeg"}],"created_by":null,"created_at":"2026-09-20T06:45:32.873817+00:00","updated_at":"2026-09-21T10:50:28.101+00:00","status":"complete","qc_reviewer_name":null,"review_date":null}'::json);
INSERT INTO "public"."complaints" SELECT * FROM json_populate_record(NULL::"public"."complaints", '{"id":657,"complaint_no":"CMP-IMPORTED-0657","customer_name":"JEHAN ABDULMAJEED HASAN ABDULLA","delivery_date":"2026-04-01","complaint_type":"Product","material_type":"8\" LINED BLOCKS","details":"Cracks","solution":"Site has been visited and we found 19 blocks with crack the customer asked to return the blocks This happen coz of the cuber attender didint remove the rejected clocks and it has been supplayed to the customer","recommendation":"We have informed the cuber attender to double check.","picture_paths":[],"created_by":null,"created_at":"2026-09-20T06:45:32.955016+00:00","updated_at":"2026-09-20T07:03:16.62+00:00","status":"complete","qc_reviewer_name":null,"review_date":null}'::json);
INSERT INTO "public"."complaints" SELECT * FROM json_populate_record(NULL::"public"."complaints", '{"id":658,"complaint_no":"CMP-IMPORTED-0658","customer_name":"BANI JAMRAH CHARITY SOCIETY","delivery_date":"2026-01-27","complaint_type":"Product","material_type":"80mm Grey ( Grade 2).","details":"Different size in interlock","solution":"Site has been visited, and the customer was taking second-quality materials at a special price. That is why there was a difference from batch to batch. I convinced the customer to mix and use the materials, and he agreed. After that, he requested an extra 100 m. I informed him that this would not match the existing line, and he agreed to proceed with the supply and use.","recommendation":"there are no steps.","picture_paths":[],"created_by":null,"created_at":"2026-09-20T06:45:32.955016+00:00","updated_at":"2026-09-20T07:03:16.623+00:00","status":"complete","qc_reviewer_name":null,"review_date":null}'::json);
INSERT INTO "public"."complaints" SELECT * FROM json_populate_record(NULL::"public"."complaints", '{"id":659,"complaint_no":"CMP-IMPORTED-0659","customer_name":"QASSIM ALI","delivery_date":"2026-03-30","complaint_type":"Product","material_type":"DOUBLE WASHED SAND","details":"Too much dust in D.W. sand","solution":"The site was visited, and the customer reported that shell smaller than 2 mm were present in the sand, which was causing cracks in the plaster work. Action taken: 5 ton were replaced with new sand","recommendation":"Plaster sand has been received from other suppliers.","picture_paths":[],"created_by":null,"created_at":"2026-09-20T06:45:32.955016+00:00","updated_at":"2026-09-20T07:03:16.626+00:00","status":"complete","qc_reviewer_name":null,"review_date":null}'::json);
INSERT INTO "public"."complaints" SELECT * FROM json_populate_record(NULL::"public"."complaints", '{"id":660,"complaint_no":"CMP-IMPORTED-0660","customer_name":"TOP JUSOOR","delivery_date":"2026-04-16","complaint_type":"Product","material_type":"35N OPC","details":"Receiving 100mm slump Only.","solution":"Our technician was present at site, and the slump was checked and accepted by the clinet as per the customer request (120 mm). This slump is requires proper vibration to ensure good compaction. The honeycombing observed is mainly due to insufficient vibration during casting, not the concrete itself.","recommendation":"He should take steps from his side.","picture_paths":[],"created_by":null,"created_at":"2026-09-20T06:45:32.955016+00:00","updated_at":"2026-09-20T07:03:16.628+00:00","status":"complete","qc_reviewer_name":null,"review_date":null}'::json);
INSERT INTO "public"."complaints" SELECT * FROM json_populate_record(NULL::"public"."complaints", '{"id":662,"complaint_no":"CMP-2026-625F89FA","customer_name":"Amwaj substation","delivery_date":"2026-09-12","complaint_type":"Crack","material_type":"Block","details":"The site consultant found a crack in the block at the middle part, so this issue consultant rejected the block.\nMy consultant said remove all the blocks from the site.","solution":"The site was visited The contractor mentioned that the consultant does not want the core bar mark on the block.\nWe suggested supplying the blocks from Khamis where the blocks do not have the core bar mark. The sample was taken from Khamis and delivered to the customer and we are now waiting for the consultant approval.","recommendation":"The production team can work on fixing this issue since its most probably related to the mold used neither mix design nor transportation.","picture_paths":[{"size": 756351, "mimeType": "image/jpeg", "objectPath": "/objects/uploads/840a2003-ad2c-4166-8f40-727c09fc384f", "originalName": "WhatsApp Image 2026-09-24 at 13.33.15 (1).jpeg"}, {"size": 145234, "mimeType": "image/jpeg", "objectPath": "/objects/uploads/cb8cc8bd-b0b6-4ab8-9c75-61e0d39e555d", "originalName": "WhatsApp Image 2026-09-24 at 13.33.15.jpeg"}, {"size": 385639, "mimeType": "image/jpeg", "objectPath": "/objects/uploads/a6f8f8de-38d8-4945-b89d-074feeeb5bfb", "originalName": "WhatsApp Image 2026-09-24 at 13.33.16 (1).jpeg"}, {"size": 152976, "mimeType": "image/jpeg", "objectPath": "/objects/uploads/51234f77-a99a-4f8a-b579-6cbfb445ba25", "originalName": "WhatsApp Image 2026-09-24 at 13.33.16.jpeg"}],"created_by":"62925","created_at":"2026-09-29T12:09:25.971057+00:00","updated_at":"2026-09-29T12:16:30.976+00:00","status":"complete","qc_reviewer_name":null,"review_date":null}'::json);
INSERT INTO "public"."complaints" SELECT * FROM json_populate_record(NULL::"public"."complaints", '{"id":663,"complaint_no":"CMP-2026-57147431","customer_name":"Bahrain Mechanical Construction Co.","delivery_date":"2026-08-17","complaint_type":"Damage","material_type":"Paving","details":"We supplied smooth paving in buttermilk color. After one week of installation, the customer noticed some color variation in the paving blocks. The customer has requested us to visit the site and inspect the issue.","solution":"","recommendation":"","picture_paths":[],"created_by":"62925","created_at":"2026-09-29T12:12:30.235345+00:00","updated_at":"2026-09-29T12:12:30.235345+00:00","status":"open","qc_reviewer_name":null,"review_date":null}'::json);
INSERT INTO "public"."complaints" SELECT * FROM json_populate_record(NULL::"public"."complaints", '{"id":664,"complaint_no":"CMP-2026-829F1360","customer_name":"AL HAWI CONSTRUCTIONS","delivery_date":"2026-10-26","complaint_type":"Rejected Mix - Loose","material_type":"Ready Mix","details":"Four  ready-mix concrete trucks dispatched to Alhawi Site in Nawaderat, three of them  arrived at the site in a loose condition. The customer refused to use the concrete, and only one truck was utilized at the site.\n\nThe remaining trucks were redirected to another site; however, upon arrival, the concrete was found to be tight. Consequently.","solution":"all three trucks were rejected and therefore disposed.","recommendation":"The retardation time of Al manaratain chemical will be increased so that the mix could last longer than 2 hrs which will avoid getting tight.","picture_paths":[{"size": 30825, "mimeType": "image/png", "objectPath": "/objects/uploads/7b948e33-3895-4432-836f-d37b852edbcd", "originalName": "Capture.PNG"}],"created_by":"62925","created_at":"2026-10-31T05:10:25.469619+00:00","updated_at":"2026-11-05T10:03:51.286+00:00","status":"complete","qc_reviewer_name":"Ahmed Husham","review_date":"2026-10-29"}'::json);
