CREATE TABLE "public"."archive_documents" (
  "id" integer DEFAULT nextval('archive_documents_id_seq'::regclass) NOT NULL,
  "original_name" text NOT NULL,
  "object_path" text NOT NULL,
  "mime_type" text NOT NULL,
  "size" integer NOT NULL,
  "category" text NOT NULL,
  "subcategory" text NOT NULL,
  "description" text DEFAULT ''::text NOT NULL,
  "uploaded_by" character varying,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  "document_date" date DEFAULT CURRENT_DATE NOT NULL,
  "expiry_date" date
);

CREATE TABLE "public"."complaints" (
  "id" integer DEFAULT nextval('complaints_id_seq'::regclass) NOT NULL,
  "complaint_no" text NOT NULL,
  "customer_name" text NOT NULL,
  "delivery_date" date NOT NULL,
  "complaint_type" text NOT NULL,
  "material_type" text NOT NULL,
  "details" text NOT NULL,
  "solution" text DEFAULT ''::text NOT NULL,
  "recommendation" text DEFAULT ''::text NOT NULL,
  "picture_paths" jsonb DEFAULT '[]'::jsonb NOT NULL,
  "created_by" text,
  "created_at" timestamp with time zone DEFAULT now() NOT NULL,
  "updated_at" timestamp with time zone DEFAULT now() NOT NULL,
  "status" text DEFAULT 'open'::text NOT NULL,
  "qc_reviewer_name" text,
  "review_date" date
);

CREATE TABLE "public"."employee_access" (
